        if (count > 0)
        {
            // Get the text column that might contain block grid data
            using var colCmd = conn.CreateCommand();
            colCmd.CommandText = $"PRAGMA table_info('{pt}')";
            using var colReader = colCmd.ExecuteReader();
            var textCols = new List<string>();
            while (colReader.Read())
            {
                var colName = colReader.GetString(1);
                var colType = colReader.IsDBNull(2) ? "" : colReader.GetString(2);
                if (colType.ToLower().Contains("text") || colType.ToLower().Contains("char") || colType.ToLower().Contains("ntext"))
                    textCols.Add(colName);
            }

            foreach (var tc in textCols)
            {
                using var dataCmd = conn.CreateCommand();
                dataCmd.CommandText = $"SELECT Id, \"{tc}\" FROM \"{pt}\" WHERE \"{tc}\" LIKE '%BlockGrid%' OR \"{tc}\" LIKE '%contentData%' LIMIT 3";
                using var dataReader = dataCmd.ExecuteReader();
                while (dataReader.Read())
                {
                    var id = dataReader.GetValue(0);
                    var val = dataReader.IsDBNull(1) ? "NULL" : dataReader.GetString(1);
                    if (val?.Length > 500) val = val[..500] + "...";
                    Console.WriteLine($"\n--- {pt}(Id={id}) column '{tc}' ---");
                    Console.WriteLine(val);
                }
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error with {pt}: {ex.Message}");
    }
}

conn.Close();

