foreach (var t in tableNames)
{
    Console.WriteLine($"=== {t} schema ===");
    using var cmd2 = conn.CreateCommand();
    cmd2.CommandText = $"SELECT sql FROM sqlite_master WHERE name = '{t}'";
    Console.WriteLine(cmd2.ExecuteScalar()?.ToString() ?? "N/A");
    Console.WriteLine();
}

// Check blog post documents - join through umbracoContentVersion (id-based, not nodeId-based)
Console.WriteLine("=== Blog Content Documents ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT d.nodeId, d.published as docPublished, d.edited,
               cv.id as contentVersionId, dv.id as docVersionId,
               dv.published as versionPublished, cv.current, cv.[text] as versionText, cv.versionDate
        FROM umbracoDocument d
        JOIN umbracoContentVersion cv ON cv.nodeId = d.nodeId
        LEFT JOIN umbracoDocumentVersion dv ON dv.id = cv.id
        JOIN umbracoNode n ON n.id = d.nodeId
        WHERE n.text LIKE '%MCP%'
        ORDER BY d.nodeId, cv.createDate DESC
    ";
    using var reader = cmd.ExecuteReader();
    var cols = new List<string>();
    for (int i = 0; i < reader.FieldCount; i++) cols.Add(reader.GetName(i));
    Console.WriteLine($"Columns: {string.Join(", ", cols)}");
    while (reader.Read())
    {
        var parts = new List<string>();
        for (int i = 0; i < reader.FieldCount; i++)
            parts.Add($"{cols[i]}={reader.GetValue(i)}");
        Console.WriteLine($"  {string.Join(", ", parts)}");
    }
}

// Check published cache
