// Decompress the published cache for blog posts
Console.WriteLine("\n=== Blog Post Published Cache (decompressed) ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT nu.nodeId, nu.dataRaw FROM cmsContentNu nu WHERE nu.published = 1 AND nu.nodeId IN (1103, 1104)";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        var nodeId = reader.GetInt32(0);
        byte[] blob;
        using (var stream = reader.GetStream(1))
        using (var ms = new MemoryStream())
        {
            stream.CopyTo(ms);
            blob = ms.ToArray();
        }

        Console.WriteLine($"\n--- NodeId={nodeId}, blobSize={blob.Length} ---");
        Console.WriteLine($"  First 32 bytes: {BitConverter.ToString(blob.Take(32).ToArray())}");

        string decompressed = null;

        // Try GZip
        try
        {
            using var compressed = new MemoryStream(blob);
            using var gzip = new GZipStream(compressed, CompressionMode.Decompress);
            using var result = new MemoryStream();
            gzip.CopyTo(result);
            decompressed = Encoding.UTF8.GetString(result.ToArray());
            Console.WriteLine($"  [OK] GZip decompressed: {decompressed.Length} chars");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"  [FAIL] GZip: {ex.GetType().Name}");
        }

        // Try Deflate if GZip failed
        if (decompressed == null)
        {
            try
            {
                using var compressed = new MemoryStream(blob);
                using var deflate = new DeflateStream(compressed, CompressionMode.Decompress);
                using var result = new MemoryStream();
                deflate.CopyTo(result);
                decompressed = Encoding.UTF8.GetString(result.ToArray());
                Console.WriteLine($"  [OK] Deflate decompressed: {decompressed.Length} chars");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"  [FAIL] Deflate: {ex.GetType().Name}");
            }
        }

        // Try Brotli if others failed
        if (decompressed == null)
        {
            try
            {
                using var compressed = new MemoryStream(blob);
                using var brotli = new BrotliStream(compressed, CompressionMode.Decompress);
                using var result = new MemoryStream();
                brotli.CopyTo(result);
                decompressed = Encoding.UTF8.GetString(result.ToArray());
                Console.WriteLine($"  [OK] Brotli decompressed: {decompressed.Length} chars");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"  [FAIL] Brotli: {ex.GetType().Name}");
            }
        }

        // If still failed, try trimming the first 2 bytes (gzip header offset issue)
        if (decompressed == null && blob.Length > 2)
        {
            try
            {
                using var compressed = new MemoryStream(blob, 2, blob.Length - 2);
                using var deflate = new DeflateStream(compressed, CompressionMode.Decompress);
                using var result = new MemoryStream();
                deflate.CopyTo(result);
                decompressed = Encoding.UTF8.GetString(result.ToArray());
                Console.WriteLine($"  [OK] Deflate (skip 2 bytes): {decompressed.Length} chars");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"  [FAIL] Deflate (skip 2): {ex.GetType().Name}");
            }
        }

        if (decompressed != null)
        {
            // If it's JSON-like, search for contentData / block grid
            if (decompressed.Contains("contentData"))
            {
                Console.WriteLine($"  Contains 'contentData': Yes");
                // Show the block grid portion
                var idx = decompressed.IndexOf("contentData");
                var start = Math.Max(0, idx - 50);
                var len = Math.Min(2000, decompressed.Length - start);
                Console.WriteLine($"  Block grid segment:\n{decompressed.Substring(start, len)}");
            }
            else
            {
                Console.WriteLine($"  First 500 chars: {decompressed.Substring(0, Math.Min(500, decompressed.Length))}");
            }
        }
        else
        {
            Console.WriteLine("  Raw hex dump (first 128 bytes):");
            for (int i = 0; i < Math.Min(128, blob.Length); i += 16)
            {
                var hex = BitConverter.ToString(blob, i, Math.Min(16, blob.Length - i));
                Console.WriteLine($"    {i:X4}: {hex}");
            }
        }
    }
}

Console.WriteLine("\n=== Blog Post Property Data (umbracoPropertyData) ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT pd.versionId, n.text as nodeName, pd.propertyTypeId, pd.textValue
        FROM umbracoPropertyData pd
        JOIN umbracoContentVersion cv ON cv.id = pd.versionId
        JOIN umbracoNode n ON n.id = cv.nodeId
        WHERE cv.nodeId IN (1103, 1104) AND pd.textValue IS NOT NULL AND LENGTH(pd.textValue) > 10
        ORDER BY cv.nodeId, pd.versionId
    ";
    using var reader = cmd.ExecuteReader();
    var cols = new List<string>();
    for (int i = 0; i < reader.FieldCount; i++) cols.Add(reader.GetName(i));
    while (reader.Read())
    {
        Console.WriteLine($"\n--- VersionId={reader[0]}, Node='{reader[1]}', PropTypeId={reader[2]} ---");
        var val = reader.GetString(3);
        Console.WriteLine($"  Value length: {val.Length}");
        // Show first 2000 chars
        Console.WriteLine(val.Substring(0, Math.Min(2000, val.Length)));
    }
}

