using var conn = new SqliteConnection(connString);
conn.Open();

// Check schemas for content version tables
var tableNames = new[] { "umbracoDocumentVersion", "umbracoDocument", "umbracoContentVersion", "umbracoContent", "cmsContentNu", "umbracoPropertyData" };
foreach (var t in tableNames)
{
    Console.WriteLine($"=== {t} schema ===");
