conn.Open();

// Check cmsContentNu for ALL content nodes
Console.WriteLine("=== cmsContentNu for blog content nodes ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT nu.nodeId, nu.published, nu.rv, length(nu.dataRaw) as dataRawLen
        FROM cmsContentNu nu
        ORDER BY nu.nodeId, nu.published
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        Console.WriteLine($"nodeId={reader.GetInt32(0)} published={reader.GetInt32(1)} rv={reader.GetInt32(2)} dataRawLen={reader.GetInt32(3)}");
    }
}

// Check which nodes have dataRaw content > 100 bytes
Console.WriteLine("\n=== cmsContentNu with significant dataRaw data ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT nu.nodeId, nu.published, length(nu.dataRaw) as dataRawLen,
               typeof(nu.dataRaw) as dataType
        FROM cmsContentNu nu
        WHERE length(nu.dataRaw) > 100
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        Console.WriteLine($"nodeId={reader.GetInt32(0)} published={reader.GetInt32(1)} len={reader.GetInt32(2)} type={reader.GetString(3)}");
    }
}

// Check property data for blog content nodes
Console.WriteLine("\n=== ALL property data for current versions of blog content ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT cv.nodeId, pt.Alias as propAlias,
               length(pd.textValue) as textLen,
               substr(pd.textValue, 1, 120) as textStart
        FROM umbracoPropertyData pd
        JOIN cmsPropertyType pt ON pt.id = pd.propertyTypeId
        JOIN umbracoContentVersion cv ON cv.id = pd.versionId
        WHERE cv.current = 1 AND cv.nodeId IN (1102, 1103, 1104)
        ORDER BY cv.nodeId, pt.Alias
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        Console.WriteLine($"nodeId={reader.GetInt32(0)} prop={reader.GetString(1)} textLen={(reader.IsDBNull(2) ? -1 : reader.GetInt32(2))} textStart={reader.GetValue(3)}");
    }
}

// Check full block grid JSON for blogFrontPage
Console.WriteLine("\n=== Full block grid JSON for blogFrontPage (node 1102) blocks property ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT cv.nodeId, cv.current, length(pd.textValue) as len, pd.textValue
        FROM umbracoPropertyData pd
        JOIN cmsPropertyType pt ON pt.id = pd.propertyTypeId
        JOIN umbracoContentVersion cv ON cv.id = pd.versionId
        WHERE pt.Alias = 'blocks' AND cv.nodeId = 1102 AND cv.current = 1
    ";
    using var reader = cmd.ExecuteReader();
    if (reader.Read())
    {
        var json = reader.IsDBNull(3) ? "NULL" : reader.GetString(3);
        Console.WriteLine($"nodeId={reader.GetInt32(0)} current={reader.GetInt32(1)} len={reader.GetInt32(2)}");
        Console.WriteLine($"Full JSON:\n{json}");
    }
}

// Check content versions with document version info
Console.WriteLine("\n=== Content Versions with document version info ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT cv.id, cv.nodeId, cv.current, cv.versionDate,
               dv.published, dv.templateId
        FROM umbracoContentVersion cv
        JOIN umbracoDocumentVersion dv ON dv.id = cv.id
        WHERE cv.nodeId IN (1102, 1103, 1104)
        ORDER BY cv.nodeId, cv.versionDate DESC
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        Console.WriteLine($"verId={reader.GetInt32(0)} nodeId={reader.GetInt32(1)} current={reader.GetInt32(2)} date={reader.GetValue(3)} published={reader.GetValue(4)} templateId={reader.GetValue(5)}");
    }
}

conn.Close();

