using Microsoft.Data.Sqlite;
var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();
using var conn = new SqliteConnection(connString);
conn.Open();

// 1. Check all content types (including element types)
Console.WriteLine("=== Content Types ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT id, [key], Alias, Name, isElement FROM cmsContentType ORDER BY id";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"id={reader.GetInt32(0)} key={reader.GetString(1)} alias={reader.GetString(2)} name={reader.GetString(3)} isElement={reader.GetInt32(4)}");
}

// 2. Check: what content type does blogPost (node 1103) belong to?
Console.WriteLine("\n=== Content-node to content-type mapping ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT nodeId, contentTypeId FROM cmsContent WHERE nodeId IN (1102, 1103, 1104)";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"nodeId={reader.GetInt32(0)} contentTypeId={reader.GetInt32(1)}");
}

// 3. Property types for these content types
Console.WriteLine("\n=== Property types for blogPost content type ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT pt.id, pt.Alias, pt.Name, pt.dataTypeId
        FROM cmsPropertyType pt
        WHERE pt.contentTypeId = (SELECT contentTypeId FROM cmsContent WHERE nodeId = 1103)
        ORDER BY pt.Alias";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"id={reader.GetInt32(0)} alias={reader.GetString(1)} name={reader.GetValue(2)} dataTypeId={reader.GetInt32(3)}");
}

// 4. Data type details for block grid data types
Console.WriteLine("\n=== Data types used by blogPost properties ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT dt.id, n.text as name, dt.editorAlias, length(coalesce(dt.config, '')) as configLen
        FROM cmsDataTypes dt
        JOIN umbracoNode n ON n.id = dt.id
        WHERE dt.id IN (
            SELECT pt.dataTypeId FROM cmsPropertyType pt
            WHERE pt.contentTypeId = (SELECT contentTypeId FROM cmsContent WHERE nodeId = 1103)
        )
        ORDER BY n.text";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"id={reader.GetInt32(0)} name={reader.GetString(1)} editor={reader.GetString(2)} configLen={reader.GetInt32(3)}");
}

// 5. Check which nodeId the "content" property data type refers to
Console.WriteLine("\n=== Block grid data types and their nodeId ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT dt.id, dt.nodeId, n.text as name, dt.editorAlias, length(coalesce(dt.config, '')) as configLen
        FROM cmsDataTypes dt
        JOIN umbracoNode n ON n.id = dt.id
        WHERE dt.editorAlias = 'Umbraco.BlockGrid'
        ORDER BY n.text";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"id={reader.GetInt32(0)} nodeId={reader.GetInt32(1)} name={reader.GetString(2)} editor={reader.GetString(3)} configLen={reader.GetInt32(4)}");
}

// 6. Element types - are they in cmsContentType cache?
Console.WriteLine("\n=== Element types check ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT ct.id, ct.key, ct.Alias, ct.Name
        FROM cmsContentType ct
        WHERE ct.Alias IN ('heroBlock', 'textBlock', 'quoteBlock', 'imageBlock')
        ORDER BY ct.Alias";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"id={reader.GetInt32(0)} key={reader.GetString(1)} alias={reader.GetString(2)} name={reader.GetString(3)}");
}

conn.Close();

