using Microsoft.Data.Sqlite;
var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();
using var conn = new SqliteConnection(connString);
conn.Open();

// Check: does the PUBLISHED version have property data too?
Console.WriteLine("=== Property data for PUBLISHED versions (not just current) ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT cv.nodeId, cv.id as versionId, cv.current, dv.published,
               pt.Alias as propAlias,
               length(pd.textValue) as textLen,
               substr(pd.textValue, 1, 150) as textStart
        FROM umbracoPropertyData pd
        JOIN cmsPropertyType pt ON pt.id = pd.propertyTypeId
        JOIN umbracoContentVersion cv ON cv.id = pd.versionId
        JOIN umbracoDocumentVersion dv ON dv.id = cv.id
        WHERE cv.nodeId IN (1102, 1103, 1104)
          AND pt.Alias IN ('content', 'blocks')
        ORDER BY cv.nodeId, dv.published DESC, cv.versionDate DESC
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        Console.WriteLine($"nodeId={reader.GetInt32(0)} verId={reader.GetInt32(1)} current={reader.GetInt32(2)} published={reader.GetInt32(3)} prop={reader.GetString(4)} textLen={(reader.IsDBNull(5) ? -1 : reader.GetInt32(5))} textStart={reader.GetValue(6)}");
    }
}

// Check all versions for blogFrontPage (1102) - does the published version have blocks data?
Console.WriteLine("\n=== ALL versions of 'blocks' property for blogFrontPage 1102 ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT cv.id as versionId, cv.current, dv.published, cv.versionDate,
               length(pd.textValue) as textLen
        FROM umbracoPropertyData pd
        JOIN cmsPropertyType pt ON pt.id = pd.propertyTypeId
        JOIN umbracoContentVersion cv ON cv.id = pd.versionId
        JOIN umbracoDocumentVersion dv ON dv.id = cv.id
        WHERE pt.Alias = 'blocks' AND cv.nodeId = 1102
        ORDER BY cv.versionDate DESC
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        Console.WriteLine($"verId={reader.GetInt32(0)} current={reader.GetInt32(1)} published={reader.GetInt32(2)} date={reader.GetValue(3)} textLen={(reader.IsDBNull(4) ? -1 : reader.GetInt32(4))}");
    }
}

// Check all versions of 'content' property for blog post 1103
Console.WriteLine("\n=== ALL versions of 'content' property for blogPost 1103 ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT cv.id as versionId, cv.current, dv.published, cv.versionDate,
               length(pd.textValue) as textLen
        FROM umbracoPropertyData pd
        JOIN cmsPropertyType pt ON pt.id = pd.propertyTypeId
        JOIN umbracoContentVersion cv ON cv.id = pd.versionId
        JOIN umbracoDocumentVersion dv ON dv.id = cv.id
        WHERE pt.Alias = 'content' AND cv.nodeId = 1103
        ORDER BY cv.versionDate DESC
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        Console.WriteLine($"verId={reader.GetInt32(0)} current={reader.GetInt32(1)} published={reader.GetInt32(2)} date={reader.GetValue(3)} textLen={(reader.IsDBNull(4) ? -1 : reader.GetInt32(4))}");
    }
}

// What about versionId=9 - the published version for blogFrontPage?
// Does it have blocks property data too?
Console.WriteLine("\n=== Property data for published versionId=9 (blogFrontPage, node 1102) ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT pt.Alias as propAlias,
               length(pd.textValue) as textLen,
               substr(pd.textValue, 1, 200) as textStart
        FROM umbracoPropertyData pd
        JOIN cmsPropertyType pt ON pt.id = pd.propertyTypeId
        WHERE pd.versionId = 9
        ORDER BY pt.Alias
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        Console.WriteLine($"prop={reader.GetString(0)} textLen={(reader.IsDBNull(1) ? -1 : reader.GetInt32(1))} textStart={reader.GetValue(2)}");
    }
}

// Now check: what does the cmsContentNu.dataRaw actually contain for the blog posts?
// Extract and try to decode the binary format
Console.WriteLine("\n=== cmsContentNu.dataRaw hex dump for blogFrontPage (1102 published=1) ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT dataRaw FROM cmsContentNu WHERE nodeId = 1102 AND published = 1";
    var result = cmd.ExecuteScalar();
    if (result is byte[] bytes)
    {
        Console.WriteLine($"Total length: {bytes.Length} bytes");
        for (int i = 0; i < Math.Min(bytes.Length, 736); i += 32)
        {
            var hex = BitConverter.ToString(bytes, i, Math.Min(32, bytes.Length - i));
            var ascii = "";
            for (int j = i; j < Math.Min(i + 32, bytes.Length); j++)
                ascii += (bytes[j] >= 32 && bytes[j] < 127) ? (char)bytes[j] : '.';
            Console.WriteLine($"{i:X4}: {hex}  {ascii}");
        }
    }
    else Console.WriteLine("No dataRaw found");
}

// Check blogPosts dataRaw
Console.WriteLine("\n=== cmsContentNu.dataRaw for blogPost 1103 (published=1) ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT dataRaw FROM cmsContentNu WHERE nodeId = 1103 AND published = 1";
    var result = cmd.ExecuteScalar();
    if (result is byte[] bytes)
    {
        Console.WriteLine($"Total length: {bytes.Length} bytes");
        for (int i = 0; i < Math.Min(bytes.Length, 1612); i += 32)
        {
            var hex = BitConverter.ToString(bytes, i, Math.Min(32, bytes.Length - i));
            var ascii = "";
            for (int j = i; j < Math.Min(i + 32, bytes.Length); j++)
                ascii += (bytes[j] >= 32 && bytes[j] < 127) ? (char)bytes[j] : '.';
            Console.WriteLine($"{i:X4}: {hex}  {ascii}");
        }
    }
    else Console.WriteLine("No dataRaw found");
}

conn.Close();

