using Microsoft.Data.Sqlite;
var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();
using var conn = new SqliteConnection(connString);
conn.Open();

// 1. Check all content types via umbracoNode join (for keys)
Console.WriteLine("=== Content Types ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT ct.pk, ct.nodeId, n.uniqueId as [key], ct.Alias, n.text as Name, ct.isElement
        FROM cmsContentType ct
        JOIN umbracoNode n ON n.id = ct.nodeId
        ORDER BY ct.pk";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"pk={reader.GetInt32(0)} nodeId={reader.GetInt32(1)} key={reader.GetString(2)} alias={reader.GetString(3)} name={reader.GetString(4)} isElement={reader.GetInt32(5)}");
}

// 2. Content types for actual content nodes
Console.WriteLine("\n=== Content node type mapping ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT c.nodeId, c.contentTypeId FROM cmsContent c WHERE c.nodeId IN (1102, 1103, 1104)";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"nodeId={reader.GetInt32(0)} contentTypeId={reader.GetInt32(1)}");
}

// 3. Check which content type pk for blog posts maps to which nodeId
Console.WriteLine("\n=== Content type for blogPost document ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT ct.pk, ct.nodeId, n.uniqueId as [key], n.text as typeName
        FROM cmsContentType ct
        JOIN umbracoNode n ON n.id = ct.nodeId
        WHERE ct.pk = (SELECT contentTypeId FROM cmsContent WHERE nodeId = 1103)";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"pk={reader.GetInt32(0)} nodeId={reader.GetInt32(1)} key={reader.GetString(2)} name={reader.GetString(3)}");
}

// 4. Property types for blog post content type
Console.WriteLine("\n=== Property types for blogPost ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT pt.id, pt.Alias, pt.Name, pt.dataTypeId, n.text as dtName
        FROM cmsPropertyType pt
        JOIN umbracoNode n ON n.id = pt.dataTypeId
        WHERE pt.contentTypeId = (SELECT contentTypeId FROM cmsContent WHERE nodeId = 1103)
        ORDER BY pt.Alias";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"id={reader.GetInt32(0)} alias={reader.GetString(1)} name={reader.GetValue(2)} dataTypeId={reader.GetInt32(3)} dtName={reader.GetString(4)}");
}

// 5. Block grid data types
Console.WriteLine("\n=== Block Grid Data Types ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT dt.id, dt.nodeId, n.text as name, dt.editorAlias, length(coalesce(dt.config, '')) as configLen
        FROM cmsDataTypes dt
        JOIN umbracoNode n ON n.id = dt.id
        WHERE dt.editorAlias = 'Umbraco.BlockGrid'
        ORDER BY n.text";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"id={reader.GetInt32(0)} nodeId={reader.GetInt32(1)} name={reader.GetString(2)} editor={reader.GetString(3)} configLen={reader.GetInt32(4)}");
}

// 6. Element types by alias
Console.WriteLine("\n=== Element types (hero/text/quote/imageBlock) ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT ct.pk, ct.nodeId, n.uniqueId as [key], ct.Alias, n.text as Name, ct.isElement
        FROM cmsContentType ct
        JOIN umbracoNode n ON n.id = ct.nodeId
        WHERE ct.Alias IN ('heroBlock', 'textBlock', 'quoteBlock', 'imageBlock')
        ORDER BY ct.Alias";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"pk={reader.GetInt32(0)} nodeId={reader.GetInt32(1)} key={reader.GetString(2)} alias={reader.GetString(3)} name={reader.GetString(4)} isElement={reader.GetInt32(5)}");
}

// 7. Check the block grid data type's config - it should contain the allowed block types
Console.WriteLine("\n=== Block Grid Data Type config ===");
using (var cmd = conn.CreateCommand())
{
    // Get first block grid data type's config
    cmd.CommandText = @"
        SELECT dt.id, n.text, dt.config
        FROM cmsDataTypes dt
        JOIN umbracoNode n ON n.id = dt.id
        WHERE dt.editorAlias = 'Umbraco.BlockGrid'
        LIMIT 1";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        Console.WriteLine($"dataTypeId={reader.GetInt32(0)} name={reader.GetString(1)}");
        if (!reader.IsDBNull(2))
        {
            var configStr = reader.GetString(2);
            Console.WriteLine($"config length: {configStr.Length}");
            Console.WriteLine($"config preview: {configStr.Substring(0, Math.Min(configStr.Length, 2000))}");
        }
    }
}

conn.Close();

