{
    cmd.CommandText = "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE '%content%' ORDER BY name";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine(reader.GetString(0));
}

Console.WriteLine("\n=== Tables like %node% ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE '%node%' ORDER BY name";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine(reader.GetString(0));
}

// Find which table maps content to content type
Console.WriteLine("\n=== Looking for content->contentType mapping ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT name FROM sqlite_master WHERE type='table' 
