using Microsoft.Data.Sqlite;
var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();
using var conn = new SqliteConnection(connString);
conn.Open();

// Check umbracoContent - what's in it?
Console.WriteLine("=== All umbracoContent ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT * FROM umbracoContent";
    using var r = cmd.ExecuteReader();
    while (r.Read()) Console.WriteLine($"nodeId={r.GetInt32(0)} contentTypeId={r.GetInt32(1)}");
}

// Check cmsPropertyType for content types 549, 550
Console.WriteLine("\n=== cmsPropertyType where contentTypeId IN (549,550) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT id, Alias, Name, dataTypeId, contentTypeId FROM cmsPropertyType WHERE contentTypeId IN (549, 550) ORDER BY contentTypeId, Alias";
    using var r = cmd.ExecuteReader();
    while (r.Read()) Console.WriteLine($"id={r.GetInt32(0)} alias={r.GetString(1)} name={r.GetValue(2)} dataTypeId={r.GetInt32(3)} contentTypeId={r.GetInt32(4)}");
}

// Check block grid data type (nodeId=1090) config
Console.WriteLine("\n=== Block grid data type (nodeId=1090) config ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT config FROM umbracoDataType WHERE nodeId = 1090";
    using var r = cmd.ExecuteReader();
    if (r.Read() && !r.IsDBNull(0)) Console.WriteLine(r.GetString(0));
}

// Check all data types referenced by the property types above
Console.WriteLine("\n=== All umbracoDataType (custom, not negative) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT nodeId, propertyEditorAlias FROM umbracoDataType WHERE nodeId > 0 ORDER BY nodeId";
    using var r = cmd.ExecuteReader();
    while (r.Read()) Console.WriteLine($"nodeId={r.GetInt32(0)} editor={r.GetString(1)}");
}

conn.Close();
