using Microsoft.Data.Sqlite;
var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();
using var conn = new SqliteConnection(connString);
conn.Open();

// Check cmsContentNu - what's in the published cache?
Console.WriteLine("=== cmsContentNu - all entries ===");
try {
    using (var cmd = conn.CreateCommand()) {
        cmd.CommandText = "SELECT nodeId, published, contentTypeAlias, dataRaw FROM cmsContentNu ORDER BY nodeId";
        using var r = cmd.ExecuteReader();
        while (r.Read()) {
            int nodeId = r.GetInt32(0);
            int published = r.GetInt32(1);
            string alias = r.GetString(2);
            byte[] raw = r.IsDBNull(3) ? null : (byte[])r["dataRaw"];
            Console.WriteLine($"nodeId={nodeId} published={published} alias={alias} dataRawLen={raw?.Length ?? 0}");
        }
    }
} catch (Exception ex) {
    Console.WriteLine($"Error: {ex.Message}");
    // Check columns
    Console.WriteLine("\n=== cmsContentNu columns ===");
    using (var cmd = conn.CreateCommand()) {
        cmd.CommandText = "PRAGMA table_info(cmsContentNu)";
        using var r = cmd.ExecuteReader();
        while (r.Read()) Console.WriteLine($"  {r.GetString(1)} ({r.GetString(2)})");
    }
}

// Check what content types are in umbracoContent
Console.WriteLine("\n=== umbracoContent (all content, with contentType joins) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT uc.nodeId, uc.contentTypeId, umb.text, ct.alias, ct.pk as ctPk
        FROM umbracoContent uc
        JOIN umbracoNode umb ON umb.id = uc.nodeId
        JOIN cmsContentType ct ON ct.nodeId = uc.contentTypeId
        ORDER BY uc.nodeId";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"nodeId={r.GetInt32(0)} contentTypeId={r.GetInt32(1)} name={r.GetValue(2)} typeAlias={r.GetString(3)} ctPk={r.GetInt32(4)}");
    }
}

// Check cmsContentType - all types (including elements)
Console.WriteLine("\n=== cmsContentType (all types) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT ct.pk, ct.nodeId, ct.alias, ct.icon, ct.isElement, un.uniqueId
        FROM cmsContentType ct
        JOIN umbracoNode un ON un.id = ct.nodeId
        ORDER BY ct.pk";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"pk={r.GetInt32(0)} nodeId={r.GetInt32(1)} alias={r.GetString(2)} icon={r.GetValue(3)} isElement={r.GetInt32(4)} key={r.GetValue(5)}");
    }
}

// Check if element types have entries in umbracoContent
Console.WriteLine("\n=== Element types (isElement=1) joined with umbracoContent ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT ct.pk, ct.nodeId, ct.alias, ct.isElement, uc.nodeId as contentNodeId
        FROM cmsContentType ct
        LEFT JOIN umbracoContent uc ON uc.contentTypeId = ct.nodeId
        WHERE ct.isElement = 1
        ORDER BY ct.pk";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"ctPk={r.GetInt32(0)} ctNodeId={r.GetInt32(1)} alias={r.GetString(2)} isElement={r.GetInt32(3)} contentNodeId={r.IsDBNull(4) ? "NULL" : r.GetInt32(4).ToString()}");
    }
}

// Check umbracoPropertyData for the block grid properties
Console.WriteLine("\n=== umbracoPropertyData for properties using dataTypeId=1090 (BlockGrid) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT pd.id, pd.documentVersionId, pd.languageId, pd.segment, pd.propertyTypeId, pd.textValue, pt.Alias, pt.Name
        FROM umbracoPropertyData pd
        JOIN cmsPropertyType pt ON pt.id = pd.propertyTypeId
        WHERE pt.dataTypeId = 1090
        ORDER BY pd.documentVersionId";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        int id = r.GetInt32(0);
        int docVerId = r.GetInt32(1);
        object lang = r.IsDBNull(2) ? null : r.GetValue(2);
        object seg = r.IsDBNull(3) ? null : r.GetValue(3);
        int ptId = r.GetInt32(4);
        string textVal = r.IsDBNull(5) ? null : r.GetString(5);
        string alias = r.GetString(6);
        string name = r.GetString(7);
        Console.WriteLine($"id={id} docVerId={docVerId} ptId={ptId} alias={alias} name={name}");
        // Print first 200 chars of textValue
        if (textVal != null) {
            Console.WriteLine($"  textValue (first 200): {textVal[..Math.Min(200, textVal.Length)]}");
            Console.WriteLine($"  textValue length: {textVal.Length}");
        } else {
            Console.WriteLine($"  textValue: NULL");
        }
    }
}

// Check document versions to understand the version chain
Console.WriteLine("\n=== umbracoDocumentVersion (last 10) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT id, versionId, documentId, published, `current`
        FROM umbracoDocumentVersion
        ORDER BY id DESC LIMIT 10";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"id={r.GetInt32(0)} versionId={r.GetValue(1)} documentId={r.GetInt32(2)} published={r.GetInt32(3)} current={r.GetInt32(4)}");
    }
}

conn.Close();

