    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"id={r.GetInt32(0)} docVerId={r.GetInt32(1)} lang={r.GetValue(2)} ptId={r.GetInt32(3)} tvLen={r.GetValue(4)}");
    }
}

// Check document version IDs to find which ones are for blog posts
Console.WriteLine("\n=== Document versions joined with content types ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT dv.id, dv.documentId, dv.published, dv.current, ct.alias
        FROM umbracoDocumentVersion dv
        JOIN umbracoContent uc ON uc.nodeId = dv.documentId
        JOIN cmsContentType ct ON ct.nodeId = uc.contentTypeId
        WHERE uc.contentTypeId IN (1092, 1093)
        ORDER BY dv.id";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"dvId={r.GetInt32(0)} docId={r.GetInt32(1)} pub={r.GetInt32(2)} cur={r.GetInt32(3)} alias={r.GetString(4)}");
    }
}

conn.Close();

