using Umbraco.Cms.Core.Services.Navigation;
using Umbraco.Cms.Infrastructure.HybridCache.Persistence;

namespace Umbraco.Cms.Infrastructure.HybridCache.SeedKeyProviders.Document;

internal sealed class ContentTypeSeedKeyProvider : IDocumentSeedKeyProvider, ISeedKeyProvider
{
	private readonly ICoreScopeProvider _scopeProvider;

	private readonly IDatabaseCacheRepository _databaseCacheRepository;

	private readonly IDocumentPublishStatusQueryService _publishStatusService;

	private readonly CacheSettings _cacheSettings;

	public ContentTypeSeedKeyProvider(ICoreScopeProvider scopeProvider, IDatabaseCacheRepository databaseCacheRepository, IOptions<CacheSettings> cacheSettings, IDocumentPublishStatusQueryService publishStatusService)
	{
		_scopeProvider = scopeProvider;
		_databaseCacheRepository = databaseCacheRepository;
		_publishStatusService = publishStatusService;
		_cacheSettings = cacheSettings.Value;
	}

	public ISet<Guid> GetSeedKeys()
	{
		ICoreScope val = _scopeProvider.CreateCoreScope(IsolationLevel.Unspecified, (RepositoryCacheMode)0, (IEventDispatcher)null, (IScopedNotificationPublisher)null, (bool?)null, false, false);
		try
		{
			HashSet<Guid> result = (from key in _databaseCacheRepository.GetDocumentKeysByContentTypeKeys(_cacheSettings.ContentTypeKeys, published: true)
				where _publishStatusService.IsPublishedInAnyCulture(key)
				select key).ToHashSet();
			val.Complete();
			return result;
		}
		finally
		{
			((IDisposable)val)?.Dispose();
		}
	}
}

