    cmd.CommandText = @"
        SELECT c.alias as contentTypeAlias, pt.Alias as propAlias, pt.Name as propName
        FROM cmsPropertyType pt
        JOIN cmsContentType c ON c.nodeId = pt.contentTypeId
        WHERE pt.dataTypeId = 1090";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"contentType={r.GetString(0)} propAlias={r.GetString(1)} propName={r.GetString(2)}");
    }
}

