                Console.Write(char.IsControl(c) ? '.' : c);
            }
            Console.WriteLine();
        }
    }
}

// Check umbracoPropertyData entries across all properties
Console.WriteLine("\n=== umbracoPropertyData - all entries (for documents with content type blogPost) ===");
