conn.Open();

// Find template tables
Console.WriteLine("=== Tables matching '%template%' ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE '%template%' ORDER BY name";
    using var r = cmd.ExecuteReader();
    while (r.Read()) Console.WriteLine(r.GetString(0));
}

// Check DocumentVersion columns
Console.WriteLine("\n=== umbracoDocumentVersion all data ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT * FROM umbracoDocumentVersion";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        for (int i = 0; i < r.FieldCount; i++) 
            Console.Write($"  {r.GetName(i)}={r.GetValue(i)}");
        Console.WriteLine();
    }
}

// Map version IDs to nodes via ContentVersion
Console.WriteLine("\n=== Map property data versions to nodes ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT up.versionId, cv.nodeId, un.text as name, ct.alias as type
        FROM umbracoPropertyData up
        JOIN umbracoContentVersion cv ON cv.id = up.versionId
        JOIN umbracoNode un ON un.id = cv.nodeId
        JOIN cmsContentType ct ON ct.nodeId = (SELECT contentTypeId FROM umbracoContent WHERE nodeId = cv.nodeId)
        GROUP BY up.versionId
        ORDER BY up.versionId";
    using var r = cmd.ExecuteReader();
    while (r.Read()) 
        Console.WriteLine($"verId={r.GetValue(0)} nodeId={r.GetInt32(1)} name={r.GetString(2)} type={r.GetString(3)}");
}

