        WHERE pt.alias = 'content' AND up.textValue IS NOT NULL
        LIMIT 1";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        string val = r.GetString(0);
        Console.WriteLine($"Length: {val.Length}");
        Console.WriteLine(val);
    }
}

// Get the 'blocks' block property value for blogFrontPage
Console.WriteLine("\n=== 'blocks' block property value for blogFrontPage ===");
